/**
 * Packs of credits as tiles: the amount, a badge, the price and a buy button. Axes: columns (2, 4), item (tile,
 * row), tone, density.
 */
import { For, type JSX } from "solid-js";
import { Badge, Box, Button, Card, CardContent, Grid, Stack, Text, Title } from "../compose";
import { EmptyState } from "../components/empty-state";
import { SectionFrame } from "../components/section-frame";
import { at, cn, fitCols, fmtMoney } from "../utils";
import type { Pack } from "./credit-packs.types";

export type CreditPacksProps = {
  id: string;
  title: string;
  packs: Pack[];
  empty?: string;
  badges: Record<string, string>;
  buy: string;
  cols?: "2" | "4";
  item?: "tile" | "row";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function CreditPacks({
  id,
  title,
  packs,
  empty = "",
  badges,
  buy,
  cols = "4",
  item = "tile",
  tone = "default",
  density = "default",
  landmarkLabel,
}: CreditPacksProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      measure={(((item as string) === "row") ? "2xl" : "default")}
      landmarkLabel={landmarkLabel}
    >
      {((packs?.length ?? 0) === 0) ? (
        <EmptyState icon="coins" title={empty} />
      ) : (
        <Grid
          cols={
            (item as string) === "row" ? "1"
            : fitCols((((cols as string) === "2") ? "1-2" : "1-4"), (packs?.length ?? 0))
          }
          class="gap-4"
          data-slot="items"
        >
          <For each={packs ?? []}>{(pack) => (
            <Card
              variant="default"
              class={cn(
                "h-full",
                (
                  (item as string) === "row" ? "gap-4 p-4"
                  : (density as string) === "compact" ? "gap-4 p-4"
                  : ""
                )
              )}
              data-badge={pack.badge}
            >
              <CardContent
                class={cn(
                  "flex h-full gap-4",
                  (((item as string) === "row") ? "flex-row flex-wrap items-center justify-between" : "flex-col")
                )}
              >
                <Stack gap="2" align="start" class={cn("min-w-0", (((item as string) === "row") ? "flex-1" : ""))}>
                  {(pack.badge || (((item as string) !== "row") && (packs.filter((i) => i["badge"]).length > 0))) ? (
                    <Box class="flex min-h-6 items-center" data-slot="badge-slot">
                      {pack.badge ? (
                        <Badge variant="default" size="default" class="w-fit shrink-0">
                          {at(badges, pack.badge)}
                        </Badge>
                      ) : null}
                    </Box>
                  ) : null}
                  <Stack gap="0" class="min-w-0">
                    <Title as={3} size="xl" weight="bold">
                      {pack.name}
                    </Title>
                    <Text size="2xl" weight="bold">
                      {fmtMoney(pack.price, pack.currency)}
                    </Text>
                  </Stack>
                </Stack>
                <Button
                  variant={((pack.badge === "popular") ? "default" : "outline")}
                  size="sm"
                  type="button"
                  class={cn("w-fit shrink-0", (((item as string) === "row") ? "" : "mt-auto"))}
                >
                  {buy}
                </Button>
              </CardContent>
            </Card>
          )}</For>
        </Grid>
      )}
    </SectionFrame>
  );
}

